import { describe, expect, it } from "vitest";
import type { SceneDocument, ViewportSpec } from "../shared/contracts";
import { buildExtractorScript } from "./extractor";

const TEST_VIEWPORT: ViewportSpec = { id: "test", name: "Test", width: 25, height: 15 };

function captureScript(token: string, viewport = TEST_VIEWPORT): Promise<SceneDocument> {
  return new Promise((resolve, reject) => {
    const cleanup = () => {
      window.removeEventListener("message", receive);
      window.clearTimeout(timeout);
    };
    const receive = (event: MessageEvent) => {
      if (event.data?.token !== token) return;
      if (event.data.type === "CAPTURE_RESULT") {
        cleanup();
        resolve(event.data.scene as SceneDocument);
      } else if (event.data.type === "CAPTURE_ERROR") {
        cleanup();
        reject(new Error(event.data.message || "Capture failed."));
      }
    };
    const timeout = window.setTimeout(() => {
      cleanup();
      reject(new Error(`Capture ${token} did not complete within the test timeout.`));
    }, 5_000);
    window.addEventListener("message", receive);
    try {
      window.eval(buildExtractorScript(token, viewport, 0));
    } catch (error) {
      cleanup();
      reject(error);
    }
  });
}

function mockEnv(sizes: Map<string, { w: number; h: number }>) {
  const originalBounds = HTMLElement.prototype.getBoundingClientRect;
  const originalCss = window.CSS;
  HTMLElement.prototype.getBoundingClientRect = function () {
    const key = (this as HTMLElement).id || (this as HTMLElement).tagName;
    const size = sizes.get(key) || { w: 25, h: 15 };
    return { x: 0, y: 0, left: 0, top: 0, right: size.w, bottom: size.h, width: size.w, height: size.h, toJSON: () => ({}) };
  };
  Object.defineProperty(window, "CSS", { value: { escape: (v: string) => v }, configurable: true });
  // single-line text measurement
  const line = { x: 1, y: 1, left: 1, top: 1, right: 12, bottom: 11, width: 11, height: 10, toJSON: () => ({}) };
  const originalCreateRange = document.createRange;
  document.createRange = (() => ({ selectNodeContents: () => undefined, setStart: () => undefined, setEnd: () => undefined, getClientRects: () => [line], getBoundingClientRect: () => line })) as unknown as typeof document.createRange;
  return () => {
    HTMLElement.prototype.getBoundingClientRect = originalBounds;
    Object.defineProperty(window, "CSS", { value: originalCss, configurable: true });
    document.createRange = originalCreateRange;
  };
}

function dump(scene: SceneDocument): string {
  return scene.nodes.map((n) => `${n.id} kind=${n.kind} source=${n.source} parent=${n.parentId} children=[${n.children}] text=${JSON.stringify(n.text)}`).join("\n");
}

describe("probe 3.1", () => {
  it("zero-size wrapper with text and element children", async () => {
    document.body.innerHTML = `<div id="outer" style="width:25px;height:15px;opacity:1;visibility:visible"><div id="zero" style="width:0px;height:0px;opacity:1;visibility:visible">Zero text<span id="inner" style="opacity:1;visibility:visible">Inner text</span></div></div>`;
    document.body.style.cssText = "opacity:1;visibility:visible";
    const restore = mockEnv(new Map([["zero", { w: 0, h: 0 }]]));
    try {
      const scene = await captureScript("probe-zero");
      console.log("=== zero-size wrapper ===\n" + dump(scene));
    } finally {
      restore();
    }
  });

  it("visibility hidden wrapper with visible child", async () => {
    document.body.innerHTML = `<div id="outer" style="width:25px;height:15px;opacity:1;visibility:visible"><div id="hiddenwrap" style="width:25px;height:15px;opacity:1;visibility:hidden">Hidden text<span id="revived" style="opacity:1;visibility:visible">Revived text</span></div></div>`;
    document.body.style.cssText = "opacity:1;visibility:visible";
    const restore = mockEnv(new Map());
    try {
      const scene = await captureScript("probe-hidden");
      console.log("=== visibility hidden wrapper ===\n" + dump(scene));
    } finally {
      restore();
    }
  });

  it("display contents nested two levels with surrounding text", async () => {
    document.body.innerHTML = `<div id="outer" style="width:25px;height:15px;opacity:1;visibility:visible">Before<span id="wrap1" style="display:contents;opacity:1;visibility:visible">Mid<span id="wrap2" style="display:contents;opacity:1;visibility:visible"><em id="deep" style="opacity:1;visibility:visible">Deep text</em></span></span>After</div>`;
    document.body.style.cssText = "opacity:1;visibility:visible";
    const restore = mockEnv(new Map([["wrap1", { w: 0, h: 0 }], ["wrap2", { w: 0, h: 0 }]]));
    try {
      const scene = await captureScript("probe-nested-contents");
      console.log("=== nested display:contents ===\n" + dump(scene));
    } finally {
      restore();
    }
  });

  it("expect true to keep runner happy", () => {
    expect(true).toBe(true);
  });
});

